#!/usr/bin/env node
/**
 * Bundles every Prisma migration into one SQL file that can be pasted into a
 * database console — the Supabase SQL editor, psql, anything that takes SQL.
 *
 * This exists for the case where `prisma migrate deploy` cannot be run: no
 * checkout, no Node, no shell on a machine that can reach the database. The
 * browser SQL editor is then the only way in, and pasting the migrations by
 * hand is a trap — Prisma records what it has applied in `_prisma_migrations`,
 * so a hand-built schema leaves a non-empty database with no history, which
 * Prisma refuses to manage (P3005).
 *
 * So the bundle writes the ledger too, with the checksum Prisma itself would
 * compute: the SHA-256 of each migration.sql, verified against rows Prisma
 * wrote on a real database. A later `prisma migrate deploy` then sees every
 * migration as applied and correctly does nothing.
 *
 * Everything is one transaction. A partly-applied schema is the outcome worth
 * going out of the way to prevent, because the RLS policies land in the later
 * migrations — a schema that stops halfway has tables and no tenant isolation,
 * and nothing about it looks broken.
 *
 *   node scripts/build-schema-bundle.js [outputPath]
 */

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

const migrationsDir = path.join(__dirname, '..', 'prisma', 'migrations');
const outputPath = process.argv[2] ?? path.join(__dirname, '..', 'prisma', 'schema-bundle.sql');

const names = fs
  .readdirSync(migrationsDir)
  .filter((name) => fs.existsSync(path.join(migrationsDir, name, 'migration.sql')))
  // Prisma orders by directory name, which is timestamp-prefixed. Applying
  // these out of order would fail on the first foreign key.
  .sort();

if (!names.length) {
  console.error(`No migrations found in ${migrationsDir}`);
  process.exit(1);
}

const header = `-- ============================================================
-- PRISM-X — complete schema bootstrap
--
-- Generated by scripts/build-schema-bundle.js from prisma/migrations.
-- ${names.length} migrations, applied in order, plus the Prisma migration ledger.
--
-- Paste into the Supabase SQL editor and run once, against an EMPTY database.
-- Verify it is empty first:
--   select count(*) from pg_tables where schemaname = 'public';
--
-- Afterwards a normal \`prisma migrate deploy\` will see every migration as
-- already applied and do nothing, which is the correct outcome.
--
-- One transaction: the whole schema lands or none of it does. The RLS policies
-- are in the later migrations, so a half-applied run would leave tables with
-- no tenant isolation and no visible sign of it.
-- ============================================================

BEGIN;

CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
    "id"                  VARCHAR(36)  PRIMARY KEY NOT NULL,
    "checksum"            VARCHAR(64)  NOT NULL,
    "finished_at"         TIMESTAMPTZ,
    "migration_name"      VARCHAR(255) NOT NULL,
    "logs"                TEXT,
    "rolled_back_at"      TIMESTAMPTZ,
    "started_at"          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    "applied_steps_count" INTEGER      NOT NULL DEFAULT 0
);
`;

const parts = [header];
const applied = [];

for (const name of names) {
  const file = path.join(migrationsDir, name, 'migration.sql');
  const bytes = fs.readFileSync(file);
  applied.push({ name, checksum: crypto.createHash('sha256').update(bytes).digest('hex') });
  parts.push(`\n-- ==================== ${name} ====================\n`);
  parts.push(bytes.toString('utf8').trimEnd());
  parts.push('\n');
}

parts.push('\n-- ==================== migration ledger ====================\n');
for (const entry of applied) {
  parts.push(
    `INSERT INTO "_prisma_migrations" ` +
      `(id, checksum, finished_at, migration_name, started_at, applied_steps_count)\n` +
      `VALUES (gen_random_uuid()::text, '${entry.checksum}', now(), '${entry.name}', now(), 1)\n` +
      `ON CONFLICT DO NOTHING;\n`,
  );
}

parts.push('\nCOMMIT;\n');

const sql = parts.join('');
fs.writeFileSync(outputPath, sql);

console.log(`migrations bundled : ${names.length}`);
console.log(`output             : ${outputPath}`);
console.log(`size               : ${(sql.length / 1024).toFixed(1)} KB`);
console.log(`first              : ${names[0]}`);
console.log(`last               : ${names[names.length - 1]}`);
